     4→import apiClient from '../api/clients/apiClient';
     5→import type {
     6→  ContractGenerationRequest,
     7→  ContractGeneration,
     8→} from '../types/legal';
     9→
    10→const BASE_URL = '/operations';
    11→
    12→export const operationsService = {
    13→  /**
    14→   * Request contract generation (Operations initiates)
    15→   */
    16→  async requestContractGeneration(
    17→    request: ContractGenerationRequest
    18→  ): Promise<ContractGeneration> {
    19→    // Create FormData for multipart/form-data (backend expects Form parameters)
    20→    const formData = new FormData();
    21→    formData.append('client_nit', request.client_nit);
    22→    formData.append('contract_type', request.contract_type || 'activos');
    23→
    24→    const response = await apiClient.post<ContractGeneration>(
    25→      `${BASE_URL}/contracts/generate`,
    26→      formData,
    27→      {
    28→        headers: {
    29→          'Content-Type': 'multipart/form-data',
    30→        },
    31→      }
    32→    );
    33→    return response.data;
    34→  },
    35→
    36→  /**
    37→   * Get all approved contracts
    38→   * @param contractType - Optional filter by contract type
    39→   * @param sortBy - Optional field to sort by
    40→   * @param sortOrder - Optional sort order ('asc' or 'desc')
    41→   */
    42→  async getApprovedContracts(
    43→    contractType?: string,
    44→    sortBy?: string,
    45→    sortOrder?: string
    46→  ): Promise<ContractGeneration[]> {
    47→    const params: Record<string, string> = {};
    48→
    49→    if (contractType) {
    50→      params.contract_type = contractType;
    51→    }
    52→    if (sortBy) {
    53→      params.sort_by = sortBy;
    54→    }
    55→    if (sortOrder) {
    56→      params.sort_order = sortOrder;
    57→    }
    58→
    59→    const response = await apiClient.get<ContractGeneration[]>(
    60→      `${BASE_URL}/contracts/approved`,
    61→      { params }
    62→    );
    63→    return response.data;
    64→  },
    65→
    66→  /**
    67→   * Request Otrosí contract generation (Operations initiates)
    68→   */
    69→  async requestOtrosiGeneration(
    70→    clientNit: string
    71→  ): Promise<ContractGeneration> {
    72→    // Create FormData for multipart/form-data (backend expects Form parameters)
    73→    const formData = new FormData();
    74→    formData.append('client_nit', clientNit);
    75→    formData.append('contract_type', 'otrosi');
    76→
    77→    const response = await apiClient.post<ContractGeneration>(
    78→      `${BASE_URL}/contracts/generate`,
    79→      formData,
    80→      {
    81→        headers: {
    82→          'Content-Type': 'multipart/form-data',
    83→        },
    84→      }
    85→    );
    86→    return response.data;
    87→  },
    88→
    89→  /**
    90→   * Get all approved Otrosí contracts
    91→   */
    92→  async getApprovedOtrosis(): Promise<ContractGeneration[]> {
    93→    return this.getApprovedContracts('otrosi');
    94→  },
    95→
    96→  /**
    97→   * Request Inventario Bodega contract generation with RUT upload (Operations initiates)
    98→   *
    99→   * @param clientNit - Client NIT
   100→   * @param rutFile - RUT PDF document for custodian operator
   101→   */
   102→  async requestInventarioBodegaGeneration(
   103→    clientNit: string,
   104→    rutFile: File
   105→  ): Promise<ContractGeneration> {
   106→    // Create FormData for multipart/form-data upload
   107→    const formData = new FormData();
   108→    formData.append('client_nit', clientNit);
   109→    formData.append('contract_type', 'inventario_bodega');
   110→    formData.append('rut_file', rutFile);
   111→
   112→    const response = await apiClient.post<ContractGeneration>(
   113→      `${BASE_URL}/contracts/generate`,
   114→      formData,
   115→      {
   116→        headers: {
   117→          'Content-Type': 'multipart/form-data',
   118→        },
   119→      }
   120→    );
   121→    return response.data;
   122→  },
   123→
   124→  /**
   125→   * Get contract details by ID
   126→   */
   127→  async getContractDetails(contractId: string): Promise<ContractGeneration> {
   128→    const response = await apiClient.get<ContractGeneration>(
   129→      `${BASE_URL}/contracts/${contractId}`
   130→    );
   131→    return response.data;
   132→  },
   133→
   134→  /**
   135→   * Download approved contract PDF
   136→   */
   137→  async downloadApprovedContractPdf(contractId: string): Promise<Blob> {
   138→    const response = await apiClient.get(
   139→      `${BASE_URL}/contracts/${contractId}/download/pdf`,
   140→      {
   141→        responseType: 'blob',
   142→      }
   143→    );
   144→    return response.data;
   145→  },
   146→};
